// StaticComposedPayloadInvokeParams holds the values a parent's `<param>` and
// `namelist` give this machine's variables before it starts (§scxml-6.4.1). A
// variable left nil, or absent for an optional one, keeps the value its `<data>`
// gave it.
type StaticComposedPayloadInvokeParams struct {
	VItemCount *uint32
	VTagCount *uint32
	VWordCount *uint32
	VIdSum *uint32
	VCellSum *uint32
	VCell *uint8
	VFirstTags *uint32
	VFirstMaybe optional.Of[uint16]
	VRefusals *uint32
}

// AcceptParams gives this machine the values params carries, in place of the
// ones its `<data>` gave. Called before it initializes (§scxml-6.4.1).
func (p *StaticComposedPayloadPolicy) AcceptParams(params StaticComposedPayloadInvokeParams) {
	if params.VItemCount != nil {
		p.vItemCount = *params.VItemCount
	}
	if params.VTagCount != nil {
		p.vTagCount = *params.VTagCount
	}
	if params.VWordCount != nil {
		p.vWordCount = *params.VWordCount
	}
	if params.VIdSum != nil {
		p.vIdSum = *params.VIdSum
	}
	if params.VCellSum != nil {
		p.vCellSum = *params.VCellSum
	}
	if params.VCell != nil {
		p.vCell = *params.VCell
	}
	if params.VFirstTags != nil {
		p.vFirstTags = *params.VFirstTags
	}
	if params.VFirstMaybe.IsPresent() {
		p.vFirstMaybe = params.VFirstMaybe
	}
	if params.VRefusals != nil {
		p.vRefusals = *params.VRefusals
	}
}



// No script engine needed for this state machine, so it has no script session
// to fail and its start is never refused for one.
func (p *StaticComposedPayloadPolicy) InitializeDataModel(eng *sce.Engine[StaticComposedPayloadState, StaticComposedPayloadEvent]) *sce.ScriptSessionFailure {
	return nil
}

// SetParamValueInScriptEngine is a no-op for state machines without script engine.
func (p *StaticComposedPayloadPolicy) SetParamValueInScriptEngine(name string, value interface{}) {}


// ExecutePendingInvokes is a no-op (no invokes in this SM).
func (p *StaticComposedPayloadPolicy) ExecutePendingInvokes(engine *sce.Engine[StaticComposedPayloadState, StaticComposedPayloadEvent]) {}

// TickChildren is a no-op (no invokes in this SM).
func (p *StaticComposedPayloadPolicy) TickChildren(engine *sce.Engine[StaticComposedPayloadState, StaticComposedPayloadEvent]) {}

// DeliverToParent delivers a delayed `<send target="#_parent">` whose wait is
// over, with the payload an immediate one carries (W3C SCXML 6.2 + 6.4). It
// waited in this machine's own queue, so `<cancel>` reached it and a child that
// ended first dropped it — the engine dispatches nothing once final. Emitted for
// every machine, since the one that needs it is an invoked child, which need not
// invoke anything itself.
func (p *StaticComposedPayloadPolicy) DeliverToParent(eventName, eventData string) bool {
	if p.ParentExternalQueue == nil {
		return false
	}
	p.ParentExternalQueue.Push(sce.ParentEvent{Name: eventName, Data: eventData})
	return true
}

// HasParentSession answers whether a session invoked this one (W3C SCXML C.1):
// the queue the invoking parent installs is the link to it.
func (p *StaticComposedPayloadPolicy) HasParentSession() bool {
	return p.ParentExternalQueue != nil
}

// IsParentSession answers whether sessionID names the session that invoked this
// one (W3C SCXML C.1): the location it publishes is a target, so a reply sent to
// the origin of an event the parent sent reaches it (docs/adr/0090).
func (p *StaticComposedPayloadPolicy) IsParentSession(sessionID string) bool {
	return p.ParentExternalQueue != nil && sessionID != "" && p.ParentSessionID == sessionID
}

